   return name.charAt(0).toUpperCase();
 }

+function styleAppearanceLabel(s: StyleName): string {
+  switch (s) {
+    case "claude": return "Claude";
+    case "codex": return "Codex";
+    case "grok": return "Grok";
+  }
+}
+
