+              <div class="p-3 rounded-[var(--as-radius,0.5rem)] border border-[hsl(var(--bc)/0.08)] bg-[hsl(var(--b2)/0.15)] text-sm text-[hsl(var(--bc))]">
+                <SolidMarkdown class="prose prose-sm max-w-none [color:inherit]">
